/**
 * Provenance des notes /10 des cordages, champ par champ (C4). Demande de Pierre du 10/10/2026 :
 * « merci de vérifier les notes (souvent les notes d'origines viennent de tennis warehouse) ».
 *
 * NE MODIFIE AUCUNE NOTE : décrit d'où vient chaque note publiée dans `stringsDatabase`.
 * Codes par champ (`FieldProvenance`) :
 *   - `tw` : score Tennis Warehouse repris à l'identique (score /100 divisé par 10, ou score /10), sur
 *     une fiche qui en reprend au moins 3 (`MIN_IDENTICAL_FOR_TW`) : provenance établie ;
 *   - `inconnue:<comparaison>` : aucune source établie ; la comparaison au score TW n'est qu'un constat :
 *     `identique` (égalité isolée : le hasard en produit autant, 25 observées pour 16,6 attendues),
 *     `proche` (écart ≤ 0,5), `ecart` (> 0,5), `sans-test` (aucune revue TW trouvée par les liens du site,
 *     ou revue sans score), `non-etabli` (revue d'un produit, coloris ou jauge voisins, ou pages TW en
 *     désaccord), `sans-categorie` (TW ne note ni la polyvalence ni l'innovation) ;
 *   - `harmonisee+…` (18 cordages, 6 champs) : note publiée = moyenne (ancienne note, avis de testeurs
 *     recalé), cf. tester-ratings.ts ; la suite du code porte sur l'ancienne note `before10` ;
 *   - `testeurs` : note créée par l'harmonisation sans ancienne note (avis de testeurs recalé seul).
 * Collecte du 10/10/2026 : robots.txt respecté, robot « TennisStringAdvisor-RatingsProvenance/1.0 »,
 * ≥ 3 s entre requêtes, pages trouvées par liens (/reviewedstrings.html, pages catégorie de revues,
 * plan du site, fiches produit TW), aucune URL composée ; 109 requêtes, 1 page absente (404), aucun refus.
 * NON AFFICHÉ sur le site (contrôle 13 bis de `audit:ratings`). Les écarts ne sont pas corrigés : ils
 * relèvent d'un arbitrage de Pierre (règle C5). `lot` : commit qui a introduit les notes de la fiche.
 */

export type RatingField = 'performance' | 'control' | 'comfort' | 'durability' | 'versatility' | 'innovation' | 'spin' | 'power';
export type TwComparison = 'identique' | 'proche' | 'ecart' | 'sans-test' | 'non-etabli' | 'sans-categorie';
export type FieldProvenance = 'tw' | `inconnue:${TwComparison}` | 'harmonisee+tw' | `harmonisee+inconnue:${TwComparison}` | 'testeurs';

/** Champ du site -> catégories TW équivalentes (« Final Verdict » remplace « Overall » depuis 2023). */
export const FIELD_TO_TW: Readonly<Record<RatingField, readonly string[] | null>> = {
  performance: ['Overall', 'Final Verdict'], control: ['Control'], comfort: ['Comfort'], durability: ['Durability'],
  spin: ['Spin'], power: ['Power'], versatility: null, innovation: null,
};

/** Reprise établie : au moins 3 notes identiques au score TW sur la même fiche. */
export const MIN_IDENTICAL_FOR_TW = 3;

export interface TwReview {
  url: string;
  /** Date de consultation (AAAA-MM-JJ). */
  consultedAt: string;
  /** Date de la revue publiée par TW (AAAA-MM), null si absente. */
  reviewDate: string | null;
  title: string;
  /** Intitulé du tableau de scores (génération / jauge si TW la précise), null sinon. */
  tested: string | null;
  /** Jauge testée si TW la publie, null sinon (« jauge testée non publiée »). */
  gauge: string | null;
  /** Échelle des scores (10 ou 100) ; null : revue sans score par catégorie. */
  scale: 10 | 100 | null;
  scores: Readonly<Record<string, number>>;
}

