/** Source d'une note publiée. */
export function ratingSource(code: FieldProvenance): 'tennis-warehouse' | 'inconnue' | 'harmonisee' | 'testeurs' {
  if (code === 'tw') return 'tennis-warehouse';
  if (code === 'testeurs') return 'testeurs';
  return code.startsWith('harmonisee+') ? 'harmonisee' : 'inconnue';
}
